mapper.select:
SELECT e.* FROM un_core_event_outbox e
JOIN un_flow_action a ON a.idempotency_key = CONCAT('business-action:', e.aggregate_id)
  AND a.action_code = 'START'
JOIN un_flow_instance f ON f.id = a.instance_id AND f.started_by_account_id = a.acted_by_account_id
WHERE e.aggregate_type = 'BUSINESS_ACTION' AND e.system_id = #{actor.systemId}
  AND JSON_UNQUOTE(JSON_EXTRACT(e.payload_json, '$.action.actor.accountId')) = #{actor.accountId}
  AND JSON_UNQUOTE(JSON_EXTRACT(e.payload_json, '$.action.actor.systemId')) = #{actor.systemId}
  AND JSON_UNQUOTE(JSON_EXTRACT(e.payload_json, '$.action.actor.tenantId')) = #{actor.tenantId}
  AND JSON_UNQUOTE(JSON_EXTRACT(e.payload_json, '$.action.actor.memberId')) = #{actor.memberId}
  AND JSON_UNQUOTE(JSON_EXTRACT(e.payload_json, '$.action.actor.tenantMemberId')) = #{actor.tenantMemberId}
AND e.id < #{cursor}
ORDER BY e.id DESC LIMIT #{pageSize}

SELECT * FROM un_core_idempotency_record
WHERE context_key = #{contextKey} AND operation_code = #{operation} AND idempotency_key = #{key}
FOR UPDATE

SELECT COUNT(*) FROM un_sys_tenant_member tm
JOIN un_sys_member m ON m.id = tm.system_member_id AND m.system_id = tm.system_id
JOIN un_sys_tenant t ON t.id = tm.tenant_id AND t.system_id = tm.system_id
JOIN un_sys_system s ON s.id = tm.system_id
JOIN un_plat_account a ON a.id = m.account_id
WHERE tm.id = #{actor.tenantMemberId} AND tm.system_id = #{actor.systemId}
  AND tm.tenant_id = #{actor.tenantId} AND tm.system_member_id = #{actor.memberId}
  AND m.account_id = #{actor.accountId}
  AND tm.status = 'ACTIVE' AND m.status = 'ACTIVE' AND t.status = 'ACTIVE'
  AND s.status = 'ACTIVE' AND a.status = 'ACTIVE'

SELECT COUNT(*) FROM un_core_event_outbox e
WHERE e.aggregate_type = 'BUSINESS_ACTION' AND e.event_type = 'BUSINESS_ACTION_APPROVAL_REQUESTED'
  AND e.system_id = #{systemId} AND e.tenant_id = #{tenantId}
  AND JSON_UNQUOTE(JSON_EXTRACT(e.payload_json, '$.approvalStatus')) = 'PENDING_APPROVAL'
  AND JSON_UNQUOTE(JSON_EXTRACT(e.payload_json, '$.action.moduleCode')) = #{moduleCode}
  AND CAST(JSON_UNQUOTE(JSON_EXTRACT(e.payload_json, '$.action.recordId')) AS UNSIGNED) = #{recordId}
